{"implementation":"def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    diagnostics = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        norm_gain = gain / call['prediction_tokens']
        accepted = call['parseable'] and norm_gain >= threshold
        diagnostics.append({
            'accepted': accepted,
            'call_id': call['call_id'],
            'normalized_gain': norm_gain
        })
    accepted_call_ids = [d['call_id'] for d in diagnostics if d['accepted']]
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
